corrected_code:
from sqlalchemy import inspect
from sqlalchemy.ext.asyncio import AsyncEngine

@router.get("/database/schemas/{tenant_schema}/tables")
async def list_schema_tables(
    tenant_schema: str,
    engine: AsyncEngine = Depends(get_db_engine),
    current_user: User = Depends(get_current_user)
):
    if tenant_schema != current_user.tenant_schema and not current_user.is_superuser:
        raise HTTPException(status_code=403, detail="Forbidden: unauthorized access to tenant database schema")

    async with engine.connect() as conn:
        tables = await conn.run_sync(
            lambda sync_conn: inspect(sync_conn).get_table_names(schema=tenant_schema)
        )
    return {"schema": tenant_schema, "tables": tables}
